/*
 * A163963  First differences of A080735.
 * https://oeis.org/A163963
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = 1 unless the current cumulative sum s satisfies s+1 is
 *            prime; in that case a(n) = s+1. The sequence is generated by the
 *            recurrence b(1) = 0, a(n) = (is_prime_big(b(n)+1) ? b(n)+1 : 1),
 *            b(n+1) = b(n) + a(n)
 * Range:     u8 n <= 19, u16 n <= 83, u32 n <= 347, u64 n <= 1277,
 *            u128 n <= 4821, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"

/*  Memoized computation of a(n).  */
static seq_t *cache = NULL;       /* array of a values, 0‑based index n-1 */
static size_t cache_cap = 0;      /* allocated size of cache */
static idx_t  computed_max = 0;   /* largest n for which a(n) is stored   */
static seq_t  cum_sum = 0;        /* b(computed_max+1)                     */

/* Helper: ensure cache has capacity >= need.  */
static void ensure_cache_capacity(size_t need)
{
    if (cache_cap < need) {
        size_t new_cap = (cache_cap == 0) ? 16 : cache_cap;
        while (new_cap < need) new_cap <<= 1;
        seq_t *tmp = (new_cap == cache_cap) ? cache
                                            : (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) {
            /* In an embedded environment we would handle the error, but
               for the purposes of this function we abort.            */
            abort();
        }
        cache = tmp;
        cache_cap = new_cap;
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* safety guard, unused for OEIS offset 1 */

    /* If needed, grow the cache and compute missing values. */
    if ((idx_t)computed_max < n) {
        idx_t i;
        ensure_cache_capacity((size_t)(n));
        for (i = computed_max + 1; i <= n; ++i) {
            seq_t val = cum_sum + (seq_t)1;          /* candidate prime */
            seq_t ai = (is_prime_big(val)) ? val : (seq_t)1;
            cache[i-1] = ai;
            cum_sum += ai;
        }
        computed_max = n;
    }

    /* Return the stored value. */
    return cache[n-1];
}
